def _unpack(b64):
    return zlib.decompress(base64.b64decode("".join(b64.split()))).decode("utf-8")


def build_page():
    html = _unpack(_HTML_B64)
    # fonction lambda : évite que "\" ou "&" du code soient interprétés
    html = html.replace("/*__CSS__*/", _unpack(_CSS_B64))
    html = html.replace("/*__JS__*/", _unpack(_JS_B64))
    return html.encode("utf-8")


PAGE = build_page()
PAGE_GZ = gzip.compress(PAGE, 6)

mimetypes.add_type("video/mp4", ".mp4")
mimetypes.add_type("image/jpeg", ".jpeg")
mimetypes.add_type("image/webp", ".webp")


def _norm(s):
    """Normalise accents / casse pour retrouver un fichier malgré NFC/NFD."""
    return unicodedata.normalize("NFC", s).casefold()


def find_image(name):
    """Retourne le chemin réel d'un fichier du dossier images/ (ou None)."""
    name = os.path.basename(name.replace("\\", "/"))
    if not name or name.startswith("."):
        return None
    target = _norm(name)
    # dossier « images » ou « Image » (casse / pluriel indifférents)
    for d in ("images", "Images", "image", "Image"):
        folder = os.path.join(BASE_DIR, d)
        direct = os.path.join(folder, name)
        if os.path.isfile(direct):
            return direct
        if os.path.isdir(folder):
            for f in os.listdir(folder):
                if _norm(f) == target and os.path.isfile(os.path.join(folder, f)):
                    return os.path.join(folder, f)
    return None


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "AzurSite/1.0"

    def log_message(self, fmt, *args):
        pass

    # ---- utilitaires -------------------------------------------------
    def _send(self, code, body, ctype, extra=None, head=False):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        self.end_headers()
        if not head:
            self.wfile.write(body)

    def _page(self, head=False):
        ae = self.headers.get("Accept-Encoding", "")
        if "gzip" in ae:
            self._send(200, PAGE_GZ, "text/html; charset=utf-8",
                       {"Content-Encoding": "gzip", "Cache-Control": "no-cache"}, head)
        else:
            self._send(200, PAGE, "text/html; charset=utf-8", {"Cache-Control": "no-cache"}, head)

    def _file(self, path, head=False):
        size = os.path.getsize(path)
        ctype = mimetypes.guess_type(path)[0] or "application/octet-stream"
        start, end, code = 0, size - 1, 200
        rng = self.headers.get("Range")
        if rng:
            m = re.match(r"bytes=(\d*)-(\d*)", rng)
            if m:
                a, b = m.groups()
                if a == "" and b != "":
                    start = max(0, size - int(b))
                else:
                    start = int(a or 0)
                    if b != "":
                        end = min(int(b), size - 1)
                if start > end or start >= size:
                    self.send_response(416)
                    self.send_header("Content-Range", "bytes */%d" % size)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                code = 206
        length = end - start + 1
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Accept-Ranges", "bytes")
        self.send_header("Content-Length", str(length))
        self.send_header("Cache-Control", "public, max-age=300")
        if code == 206:
            self.send_header("Content-Range", "bytes %d-%d/%d" % (start, end, size))
        self.end_headers()
        if head:
            return
        try:
            with open(path, "rb") as f:
                f.seek(start)
                left = length
                while left > 0:
                    chunk = f.read(min(65536, left))
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    left -= len(chunk)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            pass

    # ---- routes ------------------------------------------------------
    def _route(self, head=False):
        path = unquote(urlparse(self.path).path)
        if path in ("/", "/index.html"):
            return self._page(head)
        if path.startswith("/images/"):
            real = find_image(path[len("/images/"):])
            if real:
                return self._file(real, head)
            return self._send(404, b"Image introuvable : " + path.encode("utf-8"),
                              "text/plain; charset=utf-8", head=head)
        if path == "/favicon.ico":
            return self._send(204, b"", "image/x-icon", head=head)
        if path == "/api/images":  # diagnostic : liste des photos trouvées
            names = sorted(os.listdir(IMAGES_DIR)) if os.path.isdir(IMAGES_DIR) else []
            import json
            return self._send(200, json.dumps(names, ensure_ascii=False).encode("utf-8"),
                              "application/json; charset=utf-8", head=head)
        return self._page(head)  # le site est une page unique

    def do_GET(self):
        try:
            self._route()
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            pass

    def do_HEAD(self):
        try:
            self._route(head=True)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            pass


def lan_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except OSError:
        return "127.0.0.1"


